// A tokenizer that loses nothing: Joining the text of all tokens gives the source back, byte for byte. The compiler's lexer
// skips white space and rewrites some tokens (=> becomes >=), which is right for compiling and wrong for tools that write
// source code again.
#pragma once
#include <string>
#include <string_view>
#include <vector>

namespace blitz::tools {
	enum class kind {
		word,      // Name, keyword or command, with its type character: Print, x%, name$, Offset#
		number,    // 12, 1.5, .5, 0xFF, 0b101, $FF, %101
		string,    // "text", with both quotes (the closing one may be missing at the end of a line)
		comment,   // ; to the end of the line, with the semicolon
		symbol,    // + - * / ^ = <> <= >= ( ) , . \ and other single characters
		separator, // :
		newline,   // \n, \r\n or \r
		space,     // Spaces and tabs
		other,     // Control characters and everything else that is nothing above
	};

	struct token {
		kind        type;
		std::string text; // Exactly what was in the source

		bool is(kind k) const { return type == k; }
		bool is(kind k, std::string_view s) const { return (type == k) && (text == s); }
		bool is_symbol(std::string_view s) const { return is(kind::symbol, s); }
	};

	/** Split the source into tokens. Never fails: whatever is not understood becomes a token of kind other.
	 */
	std::vector<token> tokenize(std::string_view source);

	/** Join the text of the tokens.
	 */
	std::string join(std::vector<token> const& tokens);

	/** The word in lower case, since names and keywords are not case sensitive.
	 */
	std::string lower(std::string_view text);
} // namespace blitz::tools
